script:
(function () {
  'use strict';
  // Mortgage qualifier: pass/fail for one home against several loan programs' rules.
  //   Down payment = cash available - closing costs (% of price), capped at the price.
  //   Base loan = price - down payment; loan = base loan x (1 + upfront fee %), the fee financed.
  //   Housing payment = P&I on the loan + property tax + home insurance + HOA + mortgage insurance
  //   (annual % x base loan / 12; conventional rows drop it at 20% down or more).
  //   Housing ratio = housing / gross monthly income; total DTI = (housing + other debts) / income.
  //   A program passes when the down payment meets its minimum and both ratios are within its limits
  //   (a blank housing limit means none). Highest price that passes: bisection on the price.
  // Program presets (editable on the page; checked this session):
  //   VA: 41% total DTI, no housing ratio (38 CFR 36.4340(c)-(d), eCFR); no down payment; funding fee
  //     2.15% for first use with under 5% down (VA funding fee chart, va.gov); no monthly MI.
  //   USDA guaranteed: 29% / 41% (7 CFR 3555.151(h), eCFR); no down payment; FY2026 fees 1.00% upfront,
  //     0.35% annual (rd.usda.gov; set each fiscal year).
  //   FHA: 31% / 43% with no compensating factors (HUD Handbook 4000.1 / ML 2014-02); 3.5% minimum
  //     down at a 580+ credit score; UFMIP 1.75%, annual MIP 0.55% (ML 2023-05).
  //   Conventional: 50% total DTI through Desktop Underwriter, 36% manually underwritten (Fannie Mae
  //     Selling Guide B3-6-02); 3% / 5% minimum down; private MI rate is an illustrative 0.5%.
  // Verified in Node (scratchpad mtg6/tests/mq.test.js): $375,000 home, $40,000 cash, 3% closing ->
  //   $28,750 down (7.67%); FHA loan $346,250 x 1.0175 = $352,309.38, P&I at 6.5% = $2,226.81
  //   (closed form); ratios hand-checked; max-price bisection lands where the binding rule is exactly
  //   met; income 0, blank and negative inputs show an error and never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- pure ---
  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  // b: income (monthly), debts, price, cash, closingPct, rate, months, taxPct, insYear, hoa
  // p: front (NaN = none), back, minDown, mi, upfront, drop20
  function evaluate(b, p, price) {
    var closing = price * b.closingPct / 100;
    var down = Math.min(price, Math.max(0, b.cash - closing));
    var downPct = price > 0 ? down / price * 100 : 0;
    var base = price - down;
    var loan = base * (1 + p.upfront / 100);
    var pi = payment(loan, b.rate, b.months);
    var mi = (p.drop20 && downPct >= 20) ? 0 : base * p.mi / 1200;
    var housing = pi + price * b.taxPct / 1200 + b.insYear / 12 + b.hoa + mi;
    var front = housing / b.income * 100, back = (housing + b.debts) / b.income * 100;
    var reasons = [];
    if (b.cash < closing) reasons.push('cash does not cover closing costs');
    else if (downPct + 1e-9 < p.minDown) reasons.push('down payment below ' + p.minDown + '%');
    if (!isNaN(p.front) && front > p.front + 1e-9) reasons.push('housing ratio above ' + p.front + '%');
    if (back > p.back + 1e-9) reasons.push('total DTI above ' + p.back + '%');
    return { closing: closing, down: down, downPct: downPct, base: base, loan: loan, pi: pi, mi: mi, housing: housing,
             front: front, back: back, pass: reasons.length === 0, reasons: reasons };
  }

  // Highest price (to the dollar) that passes, assuming harder to pass as the price rises. 0 if none.
  function maxPrice(b, p) {
    var lo = 0, hi = 1000;
    if (!evaluate(b, p, 1000).pass) return 0;
    while (evaluate(b, p, hi).pass && hi < 1e9) { lo = hi; hi *= 2; }
    if (hi >= 1e9) return lo;
    while (hi - lo > 1) {
      var mid = Math.floor((lo + hi) / 2);
      if (evaluate(b, p, mid).pass) lo = mid; else hi = mid;
    }
    return lo;
  }
  // --- end pure ---

  var PROGRAMS = ['Du', 'Man', 'Fha', 'Va', 'Usda'];
  var NAMES = { Du: 'Conventional (automated)', Man: 'Conventional (manual)', Fha: 'FHA', Va: 'VA', Usda: 'USDA' };

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function cell(row, text) { var td = document.createElement('td'); td.textContent = text; row.appendChild(td); return td; }

  function clearAll() {
    ['mqPassCount', 'mqDown', 'mqDebts', 'mqIncomeMo', 'mqBest'].forEach(function (id) { setText(id, '–'); });
    el('mqResults').textContent = '';
  }

  function update() {
    var b = { income: read('mqIncome', NaN) / 12, debts: read('mqCar', 0) + read('mqCards', 0) + read('mqOther', 0),
              price: read('mqPrice', NaN), cash: read('mqCash', NaN), closingPct: read('mqClosing', 0), rate: read('mqRate', NaN),
              months: parseInt(el('mqTerm').value, 10) * 12, taxPct: read('mqTax', 0), insYear: read('mqIns', 0), hoa: read('mqHoa', 0) };
    var msg = '';
    if (isNaN(b.income) || b.income <= 0) msg = 'Enter a gross annual income greater than $0.';
    else if (isNaN(b.debts) || b.debts < 0 || read('mqCar', 0) < 0 || read('mqCards', 0) < 0 || read('mqOther', 0) < 0) msg = 'Debt payments cannot be negative.';
    else if (isNaN(b.price) || b.price <= 0) msg = 'Enter a home price greater than $0.';
    else if (isNaN(b.cash) || b.cash < 0) msg = 'Enter the cash you have for the down payment and closing costs (0 or more).';
    else if (isNaN(b.rate) || b.rate < 0 || b.rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if ([b.closingPct, b.taxPct, b.insYear, b.hoa].some(function (v) { return isNaN(v) || v < 0; }) || b.closingPct > 20 || b.taxPct > 10) msg = 'Enter closing costs up to 20%, property tax up to 10% and non-negative insurance and HOA amounts.';
    var progs = [];
    if (!msg) {
      PROGRAMS.forEach(function (k) {
        var p = { key: k, front: read('mqFront' + k, NaN), back: read('mqBack' + k, NaN), minDown: read('mqMin' + k, 0),
                  mi: read('mqMi' + k, 0), upfront: read('mqUp' + k, 0), drop20: k === 'Du' || k === 'Man' };
        if (String(el('mqFront' + k).value).trim() !== '' && (isNaN(p.front) || p.front <= 0 || p.front > 100)) msg = 'Housing-ratio limits must be between 0% and 100%, or blank for no limit.';
        else if (isNaN(p.back) || p.back <= 0 || p.back > 100) msg = 'Each program needs a total DTI limit between 0% and 100%.';
        else if ([p.minDown, p.mi, p.upfront].some(function (v) { return isNaN(v) || v < 0; }) || p.minDown > 100 || p.mi > 5 || p.upfront > 10) msg = 'Minimum down must be 0–100%, mortgage insurance 0–5% and upfront fees 0–10%.';
        progs.push(p);
      });
    }
    el('mqError').hidden = !msg;
    el('mqError').textContent = msg;
    if (msg) { clearAll(); return; }

    var body = el('mqResults'), passCount = 0, best = null;
    body.textContent = '';
    var first = evaluate(b, progs[0], b.price);
    progs.forEach(function (p) {
      var r = evaluate(b, p, b.price), mp = maxPrice(b, p);
      if (r.pass) { passCount++; if (!best || r.housing < best.r.housing) best = { p: p, r: r }; }
      var tr = document.createElement('tr');
      cell(tr, NAMES[p.key]);
      var td = cell(tr, '');
      var badge = document.createElement('span');
      badge.className = 'badge ' + (r.pass ? 'badge-mint' : 'badge-blush');
      badge.textContent = r.pass ? 'Qualifies' : 'Does not qualify';
      td.appendChild(badge);
      cell(tr, money.format(r.loan));
      cell(tr, cents.format(r.housing));
      cell(tr, r.front.toFixed(1) + '%' + (isNaN(p.front) ? '' : ' / ' + p.front + '%'));
      cell(tr, r.back.toFixed(1) + '% / ' + p.back + '%');
      cell(tr, r.pass ? 'All rules met' : r.reasons.join('; '));
      cell(tr, mp > 0 ? money.format(mp) : 'None');
      body.appendChild(tr);
    });
    setText('mqPassCount', passCount + ' of ' + progs.length);
    setText('mqDown', money.format(first.down) + ' (' + first.downPct.toFixed(1) + '%)');
    setText('mqDebts', cents.format(b.debts) + ' a month');
    setText('mqIncomeMo', cents.format(b.income));
    setText('mqBest', best ? NAMES[best.p.key] + ' at ' + cents.format(best.r.housing) + ' a month' : 'No program passes at this price');
  }

  document.addEventListener('DOMContentLoaded', function () {
    ['mqForm', 'mqProgramForm'].forEach(function (id) {
      var form = el(id);
      if (!form) return;
      form.addEventListener('input', update);
      form.addEventListener('change', update);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
    });
    if (el('mqForm')) update();
  });
})();
